import AppKit

/// Floating feedback pill at the bottom-center of the screen. Never takes
/// focus (nonactivating panel ordered front without becoming key).
public final class RecordingHUD {
    public enum HUDState {
        case listening
        case processing
        case done
        case error(String)
        case copiedSecureInput
        case busy
    }

    private let panel: NSPanel
    private let label = NSTextField(labelWithString: "")
    private var hideWorkItem: DispatchWorkItem?

    public init() {
        panel = NSPanel(contentRect: NSRect(x: 0, y: 0, width: 200, height: 36),
                        styleMask: [.borderless, .nonactivatingPanel],
                        backing: .buffered, defer: true)
        panel.level = .statusBar
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.ignoresMouseEvents = true
        panel.hidesOnDeactivate = false
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]

        let effect = NSVisualEffectView(frame: panel.contentRect(forFrameRect: panel.frame))
        effect.material = .hudWindow
        effect.state = .active
        effect.blendingMode = .behindWindow
        effect.wantsLayer = true
        effect.layer?.cornerRadius = 14
        effect.layer?.masksToBounds = true
        effect.autoresizingMask = [.width, .height]

        label.font = .systemFont(ofSize: 13, weight: .medium)
        label.lineBreakMode = .byTruncatingTail
        effect.addSubview(label)
        panel.contentView = effect
    }

    public func show(_ state: HUDState) {
        hideWorkItem?.cancel()
        hideWorkItem = nil
        apply(state)
        panel.orderFrontRegardless()
    }

    public func flash(_ state: HUDState, for duration: TimeInterval = 1.2) {
        show(state)
        let item = DispatchWorkItem { [weak self] in self?.panel.orderOut(nil) }
        hideWorkItem = item
        DispatchQueue.main.asyncAfter(deadline: .now() + duration, execute: item)
    }

    public func hide() {
        hideWorkItem?.cancel()
        hideWorkItem = nil
        panel.orderOut(nil)
    }

    /// Renders the streaming transcript live while listening (Kyutai); falls
    /// back to the plain "Listening…" pill when the text is still empty.
    public func updateLiveText(_ text: String) {
        hideWorkItem?.cancel()
        hideWorkItem = nil
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty {
            apply(.listening)
        } else {
            render(symbol: "●", text: trimmed, symbolColor: .systemRed)
        }
        panel.orderFrontRegardless()
    }

    private func apply(_ state: HUDState) {
        let (symbol, text, color): (String, String, NSColor)
        switch state {
        case .listening:          (symbol, text, color) = ("●", "Listening…", .systemRed)
        case .processing:         (symbol, text, color) = ("●", "Transcribing…", .systemOrange)
        case .done:               (symbol, text, color) = ("✓", "Inserted", .systemGreen)
        case .error(let message): (symbol, text, color) = ("✕", message, .systemRed)
        case .copiedSecureInput:  (symbol, text, color) = ("⧉", "Copied — press ⌘V (secure input)", .systemYellow)
        case .busy:               (symbol, text, color) = ("●", "Still working…", .systemOrange)
        }
        render(symbol: symbol, text: text, symbolColor: color)
    }

    private func render(symbol: String, text: String, symbolColor: NSColor) {
        let font = label.font ?? .systemFont(ofSize: 13, weight: .medium)
        let attributed = NSMutableAttributedString(
            string: symbol + "  ", attributes: [.foregroundColor: symbolColor, .font: font])
        attributed.append(NSAttributedString(
            string: text, attributes: [.foregroundColor: NSColor.labelColor, .font: font]))
        label.attributedStringValue = attributed

        let textSize = attributed.size()
        let width = min(textSize.width + 36, 520)
        let height: CGFloat = 36
        panel.setContentSize(NSSize(width: width, height: height))
        label.frame = NSRect(x: 18, y: (height - textSize.height) / 2,
                             width: width - 36, height: textSize.height)
        if let screen = NSScreen.main {
            let visible = screen.visibleFrame
            panel.setFrameOrigin(NSPoint(x: visible.midX - width / 2, y: visible.minY + 60))
        }
    }
}
import AppKit

/// Small "home" window for the app — gives the Dock icon something to open
/// (clicking a Dock icon with no window feels broken). Mirrors the menu bar
/// actions for users who prefer a window.
public final class StatusWindowController: NSWindowController {
    public var onSetAPIKey: () -> Void = {}
    public var onSelectEngine: (EngineKind) -> Void = { _ in }
    public var onStartAtLogin: () -> Void = {}
    public var onQuit: () -> Void = {}

    private let statusLabel = NSTextField(labelWithString: "")
    private let enginePopup = NSPopUpButton(frame: .zero, pullsDown: false)

    public init() {
        let window = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: 440, height: 300),
            styleMask: [.titled, .closable, .miniaturizable],
            backing: .buffered, defer: false)
        window.title = "Flowstate"
        window.isReleasedWhenClosed = false
        window.center()
        super.init(window: window)
        buildContent()
    }

    required init?(coder: NSCoder) { fatalError("not used") }

    public func show() {
        NSApp.activate(ignoringOtherApps: true)
        window?.makeKeyAndOrderFront(nil)
    }

    public func update(statusText: String, selectedEngine: EngineKind) {
        statusLabel.stringValue = statusText
        if enginePopup.numberOfItems == EngineKind.allCases.count,
           let index = EngineKind.allCases.firstIndex(of: selectedEngine) {
            enginePopup.selectItem(at: index)
        }
    }

    private func buildContent() {
        guard let content = window?.contentView else { return }

        let icon = NSImageView()
        icon.image = NSApp.applicationIconImage
        icon.translatesAutoresizingMaskIntoConstraints = false
        icon.widthAnchor.constraint(equalToConstant: 72).isActive = true
        icon.heightAnchor.constraint(equalToConstant: 72).isActive = true

        let title = NSTextField(labelWithString: "Flowstate")
        title.font = .systemFont(ofSize: 22, weight: .semibold)
        title.alignment = .center

        let hint = NSTextField(labelWithString: "Hold your dictation key anywhere, speak, release.")
        hint.font = .systemFont(ofSize: 12)
        hint.textColor = .secondaryLabelColor
        hint.alignment = .center

        statusLabel.font = .systemFont(ofSize: 12, weight: .medium)
        statusLabel.alignment = .center
        statusLabel.textColor = .secondaryLabelColor
        statusLabel.lineBreakMode = .byWordWrapping
        statusLabel.maximumNumberOfLines = 2

        let keyButton = NSButton(title: "Set Groq API Key…", target: self, action: #selector(setKey))
        enginePopup.removeAllItems()
        for kind in EngineKind.allCases { enginePopup.addItem(withTitle: kind.displayName) }
        enginePopup.target = self
        enginePopup.action = #selector(engineChanged)
        let loginButton = NSButton(title: "Start at Login", target: self, action: #selector(startAtLogin))
        let quitButton = NSButton(title: "Quit Flowstate", target: self, action: #selector(quit))
        for button in [keyButton, loginButton, quitButton] {
            button.bezelStyle = .rounded
        }

        let buttons = NSStackView(views: [keyButton, enginePopup, loginButton])
        buttons.orientation = .horizontal
        buttons.spacing = 8
        buttons.distribution = .fillEqually

        let stack = NSStackView(views: [icon, title, hint, statusLabel, buttons, quitButton])
        stack.orientation = .vertical
        stack.alignment = .centerX
        stack.spacing = 12
        stack.translatesAutoresizingMaskIntoConstraints = false
        content.addSubview(stack)
        NSLayoutConstraint.activate([
            stack.centerXAnchor.constraint(equalTo: content.centerXAnchor),
            stack.centerYAnchor.constraint(equalTo: content.centerYAnchor),
            stack.leadingAnchor.constraint(greaterThanOrEqualTo: content.leadingAnchor, constant: 24),
            buttons.widthAnchor.constraint(equalTo: stack.widthAnchor),
        ])
    }

    @objc private func setKey() { onSetAPIKey() }
    @objc private func engineChanged() {
        let index = enginePopup.indexOfSelectedItem
        guard EngineKind.allCases.indices.contains(index) else { return }
        onSelectEngine(EngineKind.allCases[index])
    }
    @objc private func startAtLogin() { onStartAtLogin() }
    @objc private func quit() { onQuit() }
}
